for(const r of before.rows){const raw=fs.readFileSync(r.originalReviewFile);if(sha(raw)!==r.originalReviewSha256||!raw.equals(fs.readFileSync(r.originalReviewCopy)))throw new Error('Final original changed before authorized import');const b=JSON.parse(fs.readFileSync(r.batchFile,'utf8')),a=b.cases[r.variant].attempts.find(a=>a.attemptId===r.attemptId);if(a?.reviews?.length)throw new Error('Successful item cannot be imported twice');run('grade',String(r.sequence).padStart(2,'0')+'-'+r.variant,[path.join(root,'blocking/harness.mjs'),'grade','--batch',r.batchFile,'--review',r.originalReviewFile]);}
for(const [i,file] of before.batches.entries())run('summary','summary-'+String(i+1).padStart(2,'0'),[path.join(root,'blocking/harness.mjs'),'summary','--batch',file]);
const out=path.join(dir,'actual-import-closure.json');fs.writeFileSync(out,JSON.stringify({recordedAt:new Date().toISOString(),method:'ACTUAL_ORIGINAL_INDEPENDENT_FINAL_TECHNICAL_HARNESS_IMPORT',beforeFile,beforeSha256:sha(fs.readFileSync(beforeFile)),uniqueSuccessfulGrades:10,successfulSummaries:3,commands,originalRawFinalsUnchanged:true,noAdapterOrSemanticMutation:true,noSuccessfulItemRepeated:true,originalNotRunCasesNotGraded:true,modelOrInstallInvocation:false,counts:before.actualCounts,actualUuids:10,actualInputs:19,completeTurns:19,invalidTurns:0},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({out,sha256:sha(fs.readFileSync(out)),uniqueSuccessfulGrades:10,successfulSummaries:3,counts:before.actualCounts}));

